def duplicate_emails(person: pd.DataFrame) -> pd.DataFrame:
    df = person.groupby('email').size().reset_index().rename(columns={'email': 'x', 0: 'y'})
    df_m = person.merge(df, left_on='email', right_on='x', how='left')
