class Solution:
    def rob(self, nums: List[int]) -> int:
        def helper(nums):
            if len(nums) == 1:
                return nums[0]

            tmp1 = nums[0]
            tmp2 = max(nums[0], nums[1])

            for i in range(2, len(nums)):
                cur = max(tmp2, tmp1+nums[i])

                tmp1 = tmp2
                tmp2 = cur

            return tmp2

        if not nums:
            return
        if len(nums) == 1:
            return nums[0]

        return max(helper(nums[:len(nums)-1]), helper(nums[1:len(nums)]))

