class Solution:
    def lengthOfLIS(self, nums: List[int]) -> int:
        def binary_search(q, num):
            l, r = 0, len(q)-1
            while l <= r:
                m = (l+r)//2
                if q[m] == num:
                    return m

                if q[m] > num:
                    r = m-1
                else:
                    l = m+1

            return l

        tail = []

        for num in nums:
            k = binary_search(tail, num)

            if k == len(tail):
                tail.append(num)
            else:
                tail[k] = num

        return len(tail)

class Solution:
    def extend(self, s, i, j):
        while i >= 0 and j <= len(s)-1 and s[i] == s[j]:
            i -= 1
            j += 1
        return i+1, j-1

    def longestPalindrome(self, s: str) -> str:
        start, end = 0, 0
        for i in range(len(s)):
            l1, r1 = self.extend(s, i, i)
            l2, r2 = self.extend(s, i, i+1)
            if r1-l1 > end-start:
                start, end = l1, r1
            if r2-l2 > end-start:
                start, end = l2, r2

        return s[start: end+1]

class Solution:
    def longestCommonSubsequence(self, text1: str, text2: str) -> int:
        m, n = len(text1), len(text2)
        dp = [[0]*(n+1) for _ in range(m+1)] # dp[i][j]表示text1[:i]和text2[:j]的最长公共子序列的长度

        for i in range(1,m+1):
            for j in range(1,n+1):
                if text1[i-1] == text2[j-1]:
                    dp[i][j] = dp[i-1][j-1]+1
                else:
                    dp[i][j] = max(dp[i-1][j], dp[i][j-1])

        return dp[m][n]

class Solution:
    def minDistance(self, word1: str, word2: str) -> int:
        m, n = len(word1), len(word2)
        dp = [[0]*(n+1) for _ in range(m+1)]

        for i in range(m+1):
            dp[i][0] = i
        for j in range(n+1):
            dp[0][j] = j

        for i in range(1, m+1):
            for j in range(1, n+1):
                if word1[i-1] == word2[j-1]:
                    dp[i][j] = dp[i-1][j-1]
                else:
                    dp[i][j] = min(dp[i-1][j]+1, dp[i][j-1]+1, dp[i-1][j-1]+1)

