class Solution:
    def combinationSum(self, candidates: List[int], target: int) -> List[List[int]]:
        result = []
        def helper(tmp, i, target):
            if candidates[i] > target:
                return

            tmp.append(candidates[i])
            if candidates[i] == target:
                result.append(tmp)
                tmp.pop()
                return

            for j in range(len(candidates)):
                helper(tmp, j, target-candidates[i])

            tmp.pop()

        for i in range(len(candidates)):
            helper([], i, target)

        return result

class Solution:
    def generateParenthesis(self, n: int) -> List[str]:
        result = []
        def helper(l, r, tmp):
            if len(tmp) == 2*n:
                result.append(''.join(tmp))

            if l < n:
                tmp.append('(')
                helper(l+1, r, tmp)
                tmp.pop()
            if r < l:
                tmp.append(')')
                helper(l, r+1, tmp)
                tmp.pop()

        helper(0, 0, [])

        return result

class Solution:
    def exist(self, board: List[List[str]], word: str) -> bool:
        def helper(r, c, index):
            if index == len(word):
                return True

            if not 0 <= r <= len(board)-1 or not 0 <= c <= len(board[0])-1 or board[r][c] != word[index]:
                return False

            tmp, board[r][c] = board[r][c], '#'

            f = (
                helper(r-1, c, index+1) or
                helper(r+1, c, index+1) or
                helper(r, c-1, index+1) or
                helper(r, c+1, index+1)
            )

            board[r][c] = tmp

            return f

        for r in range(len(board)):
            for c in range(len(board[0])):
                if helper(r, c, 0):
                    return True

        return False

class Solution:
    def partition(self, s: str) -> List[List[str]]:
        def is_palindrome(s):
            '''
                判断是否是回文串
            '''
            return s == s[::-1]

        def helper(i, tmp):
            if i == len(s):
                # 本次分割结束
                result.append(tmp[:])
                return
            for j in range(i+1, len(s)+1):
                substr = s[i:j]

                if is_palindrome(substr):
                    tmp.append(substr)
                    helper(j, tmp)
                    tmp.pop()

        result = []
        helper(0, [])

        return result

class Solution:
    def numIslands(self, grid: List[List[str]]) -> int:
        def dfs(i, j):
            if not 0<=i<=len(grid)-1 or not 0<=j<=len(grid[0])-1 or grid[i][j] == '0':
                return

            grid[i][j] = '0'
            dfs(i+1, j)
            dfs(i-1, j)
            dfs(i, j+1)
            dfs(i, j-1)

        count = 0
        for i in range(len(grid)):
            for j in range(len(grid[0])):
                if grid[i][j] == '1':
                    count += 1
                    dfs(i, j)

        return count

class Solution:
    def orangesRotting(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        queue = []

        count = 0 # 新鲜橘子数量
        for i in range(n):
            for j in range(m):
                if grid[i][j] == 1:
                    count += 1
                elif grid[i][j] == 2:
                    queue.append((i, j))

        round = 0
        while len(queue)>0 and count > 0:
            round += 1
            k = len(queue)
            for i in range(k):
                (r, c) = queue.pop(0)
                if r-1 >=0 and grid[r-1][c] == 1:
                    grid[r-1][c] = 2
                    count -= 1
                    queue.append((r-1, c))
                if r+1 <= n-1 and grid[r+1][c] == 1:
                    grid[r+1][c] = 2
                    count -= 1
                    queue.append((r+1, c))
                if c-1 >= 0 and grid[r][c-1] == 1:
                    grid[r][c-1] = 2
                    count -= 1
                    queue.append((r, c-1))
                if c+1 <= m-1 and grid[r][c+1] == 1:
                    grid[r][c+1] = 2
                    count -= 1
                    queue.append((r, c+1))

        if count > 0:
            return -1
        else:
            return round

class Solution:
    def canFinish(self, numCourses: int, prerequisites: List[List[int]]) -> bool:
        inDegree = [0 for _ in range(numCourses)] # 入度表
        preList = [[] for _ in range(numCourses)] # 课程 i 的后续课程
        for cur, pre in prerequisites:
            inDegree[cur] += 1
            preList[pre].append(cur)
        # 将入度为 0 的课程入队
        queue = []
        for i in range(numCourses):
            if inDegree[i] == 0:
                queue.append(i)
        # 模拟
        while queue:
            cur = queue.pop(0)
            numCourses -= 1
            for c in preList[cur]:
                inDegree[c] -= 1
                if inDegree[c] == 0:
                    queue.append(c)
        # 判断
        return not numCourses

class Trie:

    def __init__(self):
        self.tree = [None] * 26
        self.is_end = False

    def insert(self, word: str) -> None:
        node = self
        for c in word:
            c_index = ord(c) - ord('a')
            if not node.tree[c_index]:
                node.tree[c_index] = Trie()
            node = node.tree[c_index]
        node.is_end = True

    def search(self, word: str) -> bool:
        node = self
        for c in word:
            c_index = ord(c) - ord('a')
            if not node.tree[c_index]:
                return False
            node = node.tree[c_index]
        return node.is_end

    def startsWith(self, prefix: str) -> bool:
        node = self
        for c in prefix:
            c_index = ord(c) - ord('a')
            if not node.tree[c_index]:
                return False
            node = node.tree[c_index]
        return True

