class Solution:
    def maxSlidingWindow(self, nums: List[int], k: int) -> List[int]:
        result = []
        queue = deque()
        for i, num in enumerate(nums):
            while queue and num >= nums[queue[-1]]:
                queue.pop()
            queue.append(i)
            if i-queue[0] >= k:
                queue.popleft()
            if i >= k-1:
                result.append(nums[queue[0]])
        return result

