        prenode = ListNode(0)
        prenode.next = head
        slow, fast = prenode, prenode
        for i in range(n):
            fast = fast.next
        while fast.next:
            slow, fast = slow.next, fast.next
        slow.next = slow.next.next
        return prenode.next

